import{_ as t,a as s,c as o,ac as a}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","description":"L97–L120 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课","description":"L97–L120 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-05/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 5 复习与自测","summary":"L97–L120 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课","link":"/life/english/new-concept/book-1/unit-05/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课","link":"/life/english/new-concept/book-1/unit-05/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第97–103课","link":"/life/english/new-concept/book-1/unit-05/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 5 复习与自测 · 第111–117课","link":"/life/english/new-concept/book-1/unit-05/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/review-part-02.md","filePath":"life/english/new-concept/book-1/unit-05/review-part-02.md"}'),n={name:"life/english/new-concept/book-1/unit-05/review-part-02.md"};function r(l,e,i,h,c,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-单元-5-复习与自测-·-第104–110课" tabindex="-1">第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-5-复习与自测-·-第104–110课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 5 复习与自测 · 第104–110课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-05/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-05/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-104-·-too-very-enough" tabindex="-1">Lesson 104 · too/very/enough <a class="header-anchor" href="#lesson-104-·-too-very-enough" aria-label="Permalink to &quot;Lesson 104 · too/very/enough {#lesson-104-·-too-very-enough}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This suitcase is too heavy for me to lift.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>选择 very/too：箱子重得提不起，It is ___ heavy to lift.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> too</p><p><strong>解析：</strong> 按本课规则判断：very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p></details><p><strong>表达迁移：</strong> 围绕“评价难度和完成任务的能力”写两至三句，再读给同伴听。至少使用一次too/very/enough，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This suitcase is too heavy for me to lift. The instructions are clear enough to follow.</p><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。 Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-104">回看本课</a></p><h2 id="lesson-105-·-动词-宾语-to-do" tabindex="-1">Lesson 105 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-105-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 105 · 动词 + 宾语 + to do {#lesson-105-·-动词-宾语-to-do}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Please ask Leo to check the figures.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>补小词：Ask Leo ___ check the figures.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> 按本课规则判断：want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p></details><p><strong>表达迁移：</strong> 围绕“提出要求并纠正文稿”写两至三句，再读给同伴听。至少使用一次动词 + 宾语 + to do，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please ask Leo to check the figures. I told her not to send the draft yet.</p><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。 Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-105">回看本课</a></p><h2 id="lesson-106-·-动词-宾语-to-do" tabindex="-1">Lesson 106 · 动词 + 宾语 + to do <a class="header-anchor" href="#lesson-106-·-动词-宾语-to-do" aria-label="Permalink to &quot;Lesson 106 · 动词 + 宾语 + to do {#lesson-106-·-动词-宾语-to-do}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I told her not to send the draft yet.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>补宾格：I told ___ (she) not to send it.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> her</p><p><strong>解析：</strong> 按本课规则判断：want、ask、tell 等动词可接宾语和不定式，表示希望或要求某人做某事：ask someone to check。宾语代词用 me/him/her/us/them，不用主格。否定不定式在 to 前加 not，如 tell him not to wait。want to do 是自己想做，want someone to do 是想让别人做，动作执行者不同。</p></details><p><strong>表达迁移：</strong> 围绕“提出要求并纠正文稿”写两至三句，再读给同伴听。至少使用一次动词 + 宾语 + to do，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I told her not to send the draft yet. Please ask Leo to check the figures.</p><p>Told 为过去式，her 为宾语；not to send 是否定不定式，yet 表暂时仍不要发送。 Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-106">回看本课</a></p><h2 id="lesson-107-·-形容词比较级" tabindex="-1">Lesson 107 · 形容词比较级 <a class="header-anchor" href="#lesson-107-·-形容词比较级" aria-label="Permalink to &quot;Lesson 107 · 形容词比较级 {#lesson-107-·-形容词比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This backpack is lighter than that one.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>写比较级：light → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> lighter</p><p><strong>解析：</strong> 按本课规则判断：比较两者时常用形容词比较级 + than。短形容词常加 er，如 tall→taller；辅音加 y 结尾通常变 y 为 i 再加 er，如 heavy→heavier；多音节形容词常用 more。than 后的比较对象应同类，例如 this bag 与 that one。不能同时使用 more 和 heavier。</p></details><p><strong>表达迁移：</strong> 围绕“比较两个物品的尺寸和价格”写两至三句，再读给同伴听。至少使用一次形容词比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This backpack is lighter than that one. The blue jacket is more expensive than the grey one.</p><p>Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。 More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-107">回看本课</a></p><h2 id="lesson-108-·-形容词比较级" tabindex="-1">Lesson 108 · 形容词比较级 <a class="header-anchor" href="#lesson-108-·-形容词比较级" aria-label="Permalink to &quot;Lesson 108 · 形容词比较级 {#lesson-108-·-形容词比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The blue jacket is more expensive than the grey one.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>写比较级：expensive → ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> more expensive</p><p><strong>解析：</strong> 按本课规则判断：比较两者时常用形容词比较级 + than。短形容词常加 er，如 tall→taller；辅音加 y 结尾通常变 y 为 i 再加 er，如 heavy→heavier；多音节形容词常用 more。than 后的比较对象应同类，例如 this bag 与 that one。不能同时使用 more 和 heavier。</p></details><p><strong>表达迁移：</strong> 围绕“比较两个物品的尺寸和价格”写两至三句，再读给同伴听。至少使用一次形容词比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The blue jacket is more expensive than the grey one. This backpack is lighter than that one.</p><p>More expensive 是多音节形容词比较级；the grey one 替代 the grey jacket，避免重复名词。 Lighter 是 light 的比较级；than that one 引出同类比较对象，one 替代 backpack。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-108">回看本课</a></p><h2 id="lesson-109-·-much-many-的比较级" tabindex="-1">Lesson 109 · much/many 的比较级 <a class="header-anchor" href="#lesson-109-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 109 · much/many 的比较级 {#lesson-109-·-much-many-的比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This recipe needs less sugar than the old one.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>选择 less/fewer：___ sugar.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> less</p><p><strong>解析：</strong> 按本课规则判断：much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p></details><p><strong>表达迁移：</strong> 围绕“比较数量并表达程度”写两至三句，再读给同伴听。至少使用一次much/many 的比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This recipe needs less sugar than the old one. We used fewer paper cups this week.</p><p>Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。 Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-109">回看本课</a></p><h2 id="lesson-110-·-much-many-的比较级" tabindex="-1">Lesson 110 · much/many 的比较级 <a class="header-anchor" href="#lesson-110-·-much-many-的比较级" aria-label="Permalink to &quot;Lesson 110 · much/many 的比较级 {#lesson-110-·-much-many-的比较级}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We used fewer paper cups this week.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>选择 less/fewer：___ paper cups.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fewer</p><p><strong>解析：</strong> 按本课规则判断：much 与 many 的比较级都是 more；little 表不可数数量时比较级为 less；few 对应 fewer，用于可数复数。比较水量用 more/less water，比较杯子数量用 more/fewer cups。a little 也可修饰比较级，表示稍微，如 a little cheaper。many 与 much 的选择取决于名词可数性，不能根据中文“多”判断。</p></details><p><strong>表达迁移：</strong> 围绕“比较数量并表达程度”写两至三句，再读给同伴听。至少使用一次much/many 的比较级，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We used fewer paper cups this week. This recipe needs less sugar than the old one.</p><p>Used 为过去式，fewer 修饰复数可数名词 paper cups；this week 在这里指本周已发生的用杯情况。 Needs 与单数主语 this recipe 一致；less 修饰不可数 sugar，than the old one 比较两个配方。</p></details><p><a href="/life/english/new-concept/book-1/unit-05/lesson-110">回看本课</a></p>',60)])])}const d=t(n,[["render",r]]);export{u as __pageData,d as default};
